public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
    // Construct a complete bipartite graph

    // Get the vertex sets for the left and right sides
    Set<V> leftVertices = target.getLeftVertices();
    Set<V> rightVertices = target.getRightVertices();

    // Create a vertex for the dummy sink vertex
    V sinkVertex = target.addVertex();

    // Initialize the map for edge between vertices
    Map<V, Map<V, E>> edgeMap = new HashMap<>();

    // Loop over the left vertices
    for (V leftVertex : leftVertices) {
        // Loop over the right vertices
        for (V rightVertex : rightVertices) {
            // If the vertex is not in the result map, create a new edge
            if (!resultMap.containsKey(leftVertex.toString() + " " + rightVertex.toString())) {
                E edge = target.addEdge(leftVertex, rightVertex);
                edgeMap.computeIfAbsent(leftVertex, k -> new HashMap<>());
                edgeMap.get(leftVertex).put(rightVertex, edge);
            }
        }
    }

    // Add an edge from the dummy sink vertex to all vertices on the left side
    for (V leftVertex : leftVertices) {
        target.addEdge(sinkVertex, leftVertex);
    }

    // Add an edge from all vertices on the right side to the dummy sink vertex
    for (V rightVertex : rightVertices) {
        target.addEdge(rightVertex, sinkVertex);
    }

    // Set the edge weights for all edges
    for (V leftVertex : leftVertices) {
        for (V rightVertex : rightVertices) {
            E edge = edgeMap.get(leftVertex).get(rightVertex);
            if (edge != null) {
                edge.setWeight(rightVertex.getWeight() + 1);
            }
        }
    }
}

