    Queue<Node> queue = new LinkedList<>();
    Circulator<Node> circulator = Circulator.on(queue);
    Circulator.Direction direction = Circulator.Direction.FORWARD;

    // Start the traversal at the specified start node
    circulator.moveTo(start, dir);

    // Iterate over the nodes until we find a node that satisfies the predicate
    while (circulator.hasNext()) {
        Node node = circulator.next();
        if (predicate.test(node)) {
            return circulator;
        }
        queue.add(node);
    }

    // If we reached the end of the component without finding a node that
    // satisfies the predicate, return the stop node
    return circulator.moveTo(stop, dir);
}

