private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Loop through the bytes in the ByteBuffer
    while (i < bb.capacity()) {
        // Check if the next byte is a UTF-8 continuation byte
        if ((bb.get(i) & 0xC0) != 0x80) {
            // If it's not, append the byte to the StringBuilder
            sb.append((char) bb.get(i));
        } else {
            // If it is, use the UTF-8 code point decoder to construct the character
            int codePoint = 0;
            while ((bb.get(i) & 0x80) == 0x80) {
                codePoint = (codePoint << 6) | (bb.get(i) & 0x3F);
                i++;
            }
            sb.append((char) codePoint);
        }
        i++;
    }

    return i;
}

