public static Type resolveBound(TypeVariable<?> typeVariable) {
    // Check if the type variable has a declared bound
    Type[] bounds = typeVariable.getBounds();
    if (bounds != null && bounds.length > 0) {
        // Return the first bound that is not an instance of TypeVariable, WildcardType or GenericArrayType
        for (Type bound : bounds) {
            if (!(bound instanceof TypeVariable<?> || bound instanceof WildcardType || bound instanceof GenericArrayType)) {
                return bound;
            }
        }
    }
    // Unable to resolve the bound, return Unknown.class
    return Unknown.class;
}

