    Class foundClass = null;

    // try to load the class from the specified class loader
    try {
        foundClass = Class.forName(className, true, this.getClass().getClassLoader());
    } catch (ClassNotFoundException e) {
        // class not found, try to load from system class loader
        foundClass = Class.forName(className, true, ClassLoader.getSystemClassLoader());
