protected int removeUnusedNodes() {
    // Find all inactive nodes in the Category tree
    Set<CategoryNode> inactiveNodes = new HashSet<>();
    for (CategoryNode node : rootNodes) {
        if (!node.isActive()) {
            inactiveNodes.add(node);
        }
    }

    // Iterate through all inactive nodes and remove them from the tree
    Iterator<CategoryNode> it = inactiveNodes.iterator();
    while (it.hasNext()) {
