public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (FileInputStream inputStream = new FileInputStream(file)) {
        ThreadSnapshotParser parser = new ThreadSnapshotParser(inputStream);
        while (parser.hasNext()) {
            ThreadSnapshot snapshot = parser.next();
            ProfileAnalyzeTimeRange timeRange = new ProfileAnalyzeTimeRange(snapshot.getStartTime(), snapshot.getEndTime());
            if (timeRanges.stream().anyMatch(timeRange::overlaps)) {
                snapshots.add(snapshot);
            }
        }
    }
    return snapshots;
}

