public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int len = str.length();
    int origLen = len;
    // calculate number of bytes needed to represent the String as UTF8
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb.put(c);
        } else if (c < 0x800) {
            lb.put((byte) (0xc0 | (0x1f & (c >> 6)));
            lb.put((byte) (0x80 | (0x3f & c)));
        } else if (c < 0xd800) {
            lb.put((byte) (0xe0 | (0x0f & (c >> 12))));
            lb.put((byte) (0x80 | (0x3f & (c >> 6))));
            lb.put((byte) (0x80 | (0x3f & c)));
        } else {
            // surrogate pair
            ++i;
            len++;
            int c2 = str.charAt(i);
            assert c2 >= 0xdc00 && c2 <= 0xdfff;
            c = 0x010000 + (((c & 0x3ff) << 10) | (c2 & 0x3ff));
            lb.put((byte) (0xf0 | (0x07 & (c >> 18))));
            lb.put((byte) (0x80 | (0x3f & (c >> 12))));
            lb.put((byte) (0x80 | (0x3f & (c >> 6))));
            lb.put((byte) (0x80 | (0x3f & c)));
        }
    }
    // pad string with zeros if necessary
    int p = (4 - (len % 4)) % 4;
    for (int i = 0; i < p; i++) {
        lb.put((byte)0);
    }
    // return new buffer with padded String
    return lb.putString(str.subSequence(0, origLen), p);
}

