static int writeTo(DataOutput out, LinkedBuffer buffer) throws IOException {
  // Write the number of elements in the buffer
  int size = buffer.size();
  out.writeInt(size);

  // Write each element in the buffer
  for (int i = 0; i < size; i++) {
    Object element = buffer.get(i);
    out.writeObject(element);
  }

  // Return the total content size of the buffer
  return size * (Integer.BYTES + 2);
}

